"""Typed records shared by the command line and provider implementations."""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import StrEnum
from types import MappingProxyType
from typing import Mapping


class Operation(StrEnum):
    LIST = "list"


class ProviderStatus(StrEnum):
    OK = "ok"
    UNAVAILABLE = "unavailable"
    UNSUPPORTED = "unsupported"
    ERROR = "error"


@dataclass(frozen=True, slots=True)
class ModelRecord:
    provider: str
    model_id: str
    size_bytes: int | None = None
    location: str | None = None
    attributes: Mapping[str, str] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if not self.provider:
            raise ValueError("provider must not be empty")
        if not self.model_id:
            raise ValueError("model_id must not be empty")
        if self.size_bytes is not None and self.size_bytes < 0:
            raise ValueError("size_bytes must not be negative")
        normalized = dict(sorted(self.attributes.items()))
        if any(not isinstance(key, str) or not isinstance(value, str) for key, value in normalized.items()):
            raise TypeError("attribute keys and values must be strings")
        object.__setattr__(self, "attributes", MappingProxyType(normalized))

    def to_dict(self) -> dict[str, object]:
        return {
            "attributes": dict(self.attributes),
            "location": self.location,
            "model_id": self.model_id,
            "provider": self.provider,
            "size_bytes": self.size_bytes,
        }


@dataclass(frozen=True, slots=True)
class ProviderResult:
    provider: str
    operation: Operation
    status: ProviderStatus
    records: tuple[ModelRecord, ...] = ()
    message: str | None = None

    def __post_init__(self) -> None:
        if not self.provider:
            raise ValueError("provider must not be empty")
        if self.status is ProviderStatus.OK and self.message is not None:
            raise ValueError("successful results must not contain an error message")
        if self.status is not ProviderStatus.OK and not self.message:
            raise ValueError("unsuccessful results must contain an error message")
        if any(record.provider != self.provider for record in self.records):
            raise ValueError("record provider must match result provider")

    @classmethod
    def success(
        cls,
        provider: str,
        operation: Operation,
        records: tuple[ModelRecord, ...] = (),
    ) -> ProviderResult:
        ordered = tuple(
            sorted(records, key=lambda record: (record.model_id, record.location or ""))
        )
        return cls(provider, operation, ProviderStatus.OK, ordered)

    @classmethod
    def failure(
        cls,
        provider: str,
        operation: Operation,
        status: ProviderStatus,
        message: str,
        records: tuple[ModelRecord, ...] = (),
    ) -> ProviderResult:
        if status is ProviderStatus.OK:
            raise ValueError("failure status must not be ok")
        ordered = tuple(
            sorted(records, key=lambda record: (record.model_id, record.location or ""))
        )
        return cls(provider, operation, status, ordered, message)

    def to_dict(self) -> dict[str, object]:
        return {
            "message": self.message,
            "operation": self.operation.value,
            "provider": self.provider,
            "records": [record.to_dict() for record in self.records],
            "status": self.status.value,
        }

"""Command-line interface for model storage checks."""

from __future__ import annotations

import argparse
import json
import math
import sys
from collections.abc import Sequence
from typing import TextIO

from .errors import (
    ProviderFailureError,
    ProviderUnavailableError,
    UnsupportedOperationError,
    UnsupportedProviderError,
)
from .lm_studio import (
    DEFAULT_BASE_URL as DEFAULT_LM_STUDIO_BASE_URL,
    DEFAULT_MODEL_ROOTS,
    DEFAULT_TIMEOUT as DEFAULT_LM_STUDIO_TIMEOUT,
    LMStudioConfig,
)
from .models import Operation, ProviderResult, ProviderStatus
from .ollama import DEFAULT_BASE_URL, DEFAULT_TIMEOUT, OllamaConfig
from .providers import DEFAULT_REGISTRY, ProviderRegistry, create_default_registry

EXIT_ERROR = 1
EXIT_USAGE = 2
EXIT_UNAVAILABLE = 3
EXIT_UNSUPPORTED = 4


def _positive_timeout(value: str) -> float:
    try:
        timeout = float(value)
    except ValueError as error:
        raise argparse.ArgumentTypeError("must be a number") from error
    if not math.isfinite(timeout) or timeout <= 0:
        raise argparse.ArgumentTypeError(
            "must be a finite number greater than zero"
        )
    return timeout


def _ollama_base_url(value: str) -> str:
    try:
        return OllamaConfig(base_url=value).base_url
    except ValueError as error:
        raise argparse.ArgumentTypeError(str(error)) from error


def _lm_studio_base_url(value: str) -> str:
    try:
        return LMStudioConfig(base_url=value).base_url
    except ValueError as error:
        raise argparse.ArgumentTypeError(str(error)) from error


def build_parser(registry: ProviderRegistry = DEFAULT_REGISTRY) -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="model-storage-checker",
        description="Report locally stored models from read-only providers.",
    )
    parser.add_argument(
        "operation",
        choices=tuple(operation.value for operation in Operation),
        help="read-only operation to perform",
    )
    parser.add_argument(
        "--provider",
        action="append",
        choices=registry.names,
        dest="providers",
        help="provider to check; repeat to select multiple (default: all)",
    )
    parser.add_argument(
        "--output",
        choices=("text", "json"),
        default="text",
        help="output format (default: text)",
    )
    parser.add_argument(
        "--ollama-base-url",
        default=DEFAULT_BASE_URL,
        type=_ollama_base_url,
        help=f"Ollama service base URL (default: {DEFAULT_BASE_URL})",
    )
    parser.add_argument(
        "--ollama-timeout",
        default=DEFAULT_TIMEOUT,
        type=_positive_timeout,
        metavar="SECONDS",
        help=f"Ollama request timeout in seconds (default: {DEFAULT_TIMEOUT:g})",
    )
    parser.add_argument(
        "--lm-studio-base-url",
        default=DEFAULT_LM_STUDIO_BASE_URL,
        type=_lm_studio_base_url,
        help=(
            "LM Studio OpenAI-compatible base URL "
            f"(default: {DEFAULT_LM_STUDIO_BASE_URL})"
        ),
    )
    parser.add_argument(
        "--lm-studio-timeout",
        default=DEFAULT_LM_STUDIO_TIMEOUT,
        type=_positive_timeout,
        metavar="SECONDS",
        help=(
            "LM Studio request timeout in seconds "
            f"(default: {DEFAULT_LM_STUDIO_TIMEOUT:g})"
        ),
    )
    parser.add_argument(
        "--lm-studio-model-root",
        action="append",
        dest="lm_studio_model_roots",
        metavar="PATH",
        help=(
            "LM Studio model root to scan recursively; repeat for multiple roots "
            f"(default: {DEFAULT_MODEL_ROOTS[0]})"
        ),
    )
    return parser


def _failure_result(
    provider: str, operation: Operation, error: Exception
) -> ProviderResult:
    if isinstance(error, ProviderUnavailableError):
        status = ProviderStatus.UNAVAILABLE
    elif isinstance(error, (UnsupportedProviderError, UnsupportedOperationError)):
        status = ProviderStatus.UNSUPPORTED
    else:
        status = ProviderStatus.ERROR
    return ProviderResult.failure(provider, operation, status, str(error))


def collect_results(
    registry: ProviderRegistry,
    provider_names: Sequence[str],
    operation: Operation,
) -> tuple[ProviderResult, ...]:
    results: list[ProviderResult] = []
    for provider_name in sorted(set(provider_names)):
        try:
            result = registry.run(provider_name, operation)
        except (
            ProviderFailureError,
            ProviderUnavailableError,
            UnsupportedOperationError,
            UnsupportedProviderError,
        ) as error:
            result = _failure_result(provider_name, operation, error)
        results.append(result)
    return tuple(results)


def _write_json(
    stream: TextIO, operation: Operation, results: Sequence[ProviderResult]
) -> None:
    payload = {
        "operation": operation.value,
        "providers": [result.to_dict() for result in results],
        "version": 1,
    }
    json.dump(payload, stream, ensure_ascii=True, indent=2, sort_keys=True)
    stream.write("\n")


def _write_text(stream: TextIO, results: Sequence[ProviderResult]) -> None:
    for result in results:
        if result.status is ProviderStatus.OK:
            stream.write(f"{result.provider}: ok ({len(result.records)} models)\n")
        else:
            count = f" ({len(result.records)} models)" if result.records else ""
            stream.write(
                f"{result.provider}: {result.status.value}{count} - {result.message}\n"
            )
        for record in result.records:
            size = (
                f"{record.size_bytes} bytes"
                if record.size_bytes is not None
                else "size unknown"
            )
            stream.write(f"  {record.model_id} ({size})\n")


def _exit_code(results: Sequence[ProviderResult]) -> int:
    statuses = {result.status for result in results}
    if ProviderStatus.ERROR in statuses:
        return EXIT_ERROR
    if ProviderStatus.UNSUPPORTED in statuses:
        return EXIT_UNSUPPORTED
    if ProviderStatus.UNAVAILABLE in statuses:
        return EXIT_UNAVAILABLE
    return 0


def main(
    argv: Sequence[str] | None = None,
    *,
    registry: ProviderRegistry = DEFAULT_REGISTRY,
    stdout: TextIO | None = None,
) -> int:
    args = build_parser(registry).parse_args(argv)
    stream = stdout if stdout is not None else sys.stdout
    operation = Operation(args.operation)
    active_registry = registry
    if registry is DEFAULT_REGISTRY:
        active_registry = create_default_registry(
            ollama_base_url=args.ollama_base_url,
            ollama_timeout=args.ollama_timeout,
            lm_studio_base_url=args.lm_studio_base_url,
            lm_studio_timeout=args.lm_studio_timeout,
            lm_studio_model_roots=(
                tuple(args.lm_studio_model_roots)
                if args.lm_studio_model_roots is not None
                else None
            ),
        )
    provider_names = (
        args.providers if args.providers is not None else active_registry.names
    )
    results = collect_results(active_registry, provider_names, operation)

    if args.output == "json":
        _write_json(stream, operation, results)
    else:
        _write_text(stream, results)
    return _exit_code(results)

"""Errors raised by providers and provider selection."""


class ModelStorageCheckerError(Exception):
    """Base class for expected checker failures."""


class UnsupportedProviderError(ModelStorageCheckerError):
    def __init__(self, provider: str) -> None:
        self.provider = provider
        super().__init__(f"Provider {provider!r} is not supported")


class ProviderUnavailableError(ModelStorageCheckerError):
    def __init__(self, provider: str, reason: str) -> None:
        self.provider = provider
        self.reason = reason
        super().__init__(f"Provider {provider!r} is unavailable: {reason}")


class UnsupportedOperationError(ModelStorageCheckerError):
    def __init__(self, provider: str, operation: str) -> None:
        self.provider = provider
        self.operation = operation
        super().__init__(
            f"Provider {provider!r} does not support operation {operation!r}"
        )


class ProviderFailureError(ModelStorageCheckerError):
    def __init__(self, provider: str, operation: str, reason: str) -> None:
        self.provider = provider
        self.operation = operation
        self.reason = reason
        super().__init__(
            f"Provider {provider!r} failed operation {operation!r}: {reason}"
        )

"""Provider protocol and registry."""

from __future__ import annotations

from collections.abc import Iterable
from pathlib import Path
from typing import Protocol, runtime_checkable

from .errors import UnsupportedProviderError
from .lm_studio import LMStudioConfig, LMStudioProvider
from .models import Operation, ProviderResult
from .ollama import OllamaConfig, OllamaProvider


@runtime_checkable
class Provider(Protocol):
    @property
    def name(self) -> str:
        """Return the stable command-line name for this provider."""

    def run(self, operation: Operation) -> ProviderResult:
        """Run a read-only provider operation."""


class ProviderRegistry:
    def __init__(
        self,
        providers: Iterable[Provider] = (),
        *,
        unsupported_names: Iterable[str] = (),
    ) -> None:
        self._providers: dict[str, Provider] = {}
        for provider in providers:
            if provider.name in self._providers:
                raise ValueError(f"Duplicate provider name: {provider.name!r}")
            self._providers[provider.name] = provider

        unsupported = set(unsupported_names)
        overlap = self._providers.keys() & unsupported
        if overlap:
            name = sorted(overlap)[0]
            raise ValueError(f"Provider cannot also be unsupported: {name!r}")
        self._unsupported_names = frozenset(unsupported)

    @property
    def names(self) -> tuple[str, ...]:
        return tuple(sorted((*self._providers, *self._unsupported_names)))

    def run(self, provider_name: str, operation: Operation) -> ProviderResult:
        provider = self._providers.get(provider_name)
        if provider is None:
            raise UnsupportedProviderError(provider_name)
        return provider.run(operation)


def create_default_registry(
    *,
    ollama_base_url: str | None = None,
    ollama_timeout: float | None = None,
    lm_studio_base_url: str | None = None,
    lm_studio_timeout: float | None = None,
    lm_studio_model_roots: tuple[str, ...] | None = None,
) -> ProviderRegistry:
    ollama_defaults = OllamaConfig()
    ollama_config = OllamaConfig(
        base_url=ollama_base_url or ollama_defaults.base_url,
        timeout=(
            ollama_timeout if ollama_timeout is not None else ollama_defaults.timeout
        ),
    )
    lm_studio_defaults = LMStudioConfig()
    lm_studio_config = LMStudioConfig(
        base_url=lm_studio_base_url or lm_studio_defaults.base_url,
        timeout=(
            lm_studio_timeout
            if lm_studio_timeout is not None
            else lm_studio_defaults.timeout
        ),
        model_roots=(
            tuple(Path(root) for root in lm_studio_model_roots)
            if lm_studio_model_roots is not None
            else lm_studio_defaults.model_roots
        ),
    )
    return ProviderRegistry(
        (OllamaProvider(ollama_config), LMStudioProvider(lm_studio_config)),
        unsupported_names=("docker",),
    )


DEFAULT_REGISTRY = create_default_registry()

"""Read-only inventory provider for LM Studio APIs and model storage."""

from __future__ import annotations

import json
import math
import os
import socket
from collections import defaultdict
from dataclasses import dataclass
from json import JSONDecodeError
from pathlib import Path
from typing import Any, NoReturn
from urllib.error import URLError
from urllib.parse import urlsplit
from urllib.request import Request, urlopen

from .errors import (
    ProviderFailureError,
    ProviderUnavailableError,
    UnsupportedOperationError,
)
from .models import ModelRecord, Operation, ProviderResult, ProviderStatus

DEFAULT_BASE_URL = "http://127.0.0.1:1234/v1"
DEFAULT_TIMEOUT = 5.0
DEFAULT_MODEL_ROOTS = (Path.home() / ".lmstudio" / "models",)
MODEL_FILE_SUFFIXES = frozenset(
    {".bin", ".gguf", ".mlx", ".onnx", ".pt", ".pth", ".safetensors"}
)


@dataclass(frozen=True, slots=True)
class LMStudioConfig:
    base_url: str = DEFAULT_BASE_URL
    timeout: float = DEFAULT_TIMEOUT
    model_roots: tuple[Path, ...] = DEFAULT_MODEL_ROOTS

    def __post_init__(self) -> None:
        normalized_url = self.base_url.rstrip("/")
        parsed = urlsplit(normalized_url)
        if parsed.scheme not in {"http", "https"} or not parsed.netloc:
            raise ValueError("LM Studio base URL must be an absolute HTTP(S) URL")
        if parsed.query or parsed.fragment:
            raise ValueError("LM Studio base URL must not include a query or fragment")
        if not math.isfinite(self.timeout) or self.timeout <= 0:
            raise ValueError("LM Studio timeout must be a finite number greater than zero")

        roots: list[Path] = []
        for root in self.model_roots:
            path = Path(root).expanduser().resolve(strict=False)
            if path not in roots:
                roots.append(path)
        object.__setattr__(self, "base_url", normalized_url)
        object.__setattr__(self, "model_roots", tuple(roots))


class LMStudioProvider:
    name = "lm-studio"

    def __init__(self, config: LMStudioConfig | None = None) -> None:
        self.config = config if config is not None else LMStudioConfig()

    def run(self, operation: Operation) -> ProviderResult:
        if operation is not Operation.LIST:
            raise UnsupportedOperationError(self.name, operation.value)

        api_records: list[ModelRecord] = []
        file_records: list[ModelRecord] = []
        issues: list[tuple[ProviderStatus, str]] = []

        try:
            api_records = self._parse_api_records(self._fetch_models(), operation)
        except ProviderUnavailableError as error:
            issues.append(
                (ProviderStatus.UNAVAILABLE, f"API discovery failed: {error.reason}")
            )
        except ProviderFailureError as error:
            issues.append((ProviderStatus.ERROR, f"API discovery failed: {error.reason}"))

        file_records, file_errors = self._discover_files()
        issues.extend(
            (ProviderStatus.ERROR, f"filesystem discovery failed: {error}")
            for error in file_errors
        )

        records = tuple(self._deduplicate(api_records, file_records))
        if not issues:
            return ProviderResult.success(self.name, operation, records)

        status = (
            ProviderStatus.ERROR
            if any(item_status is ProviderStatus.ERROR for item_status, _ in issues)
            else ProviderStatus.UNAVAILABLE
        )
        return ProviderResult.failure(
            self.name,
            operation,
            status,
            "; ".join(message for _, message in issues),
            records,
        )

    def _fetch_models(self) -> object:
        endpoint = f"{self.config.base_url}/models"
        request = Request(
            endpoint,
            headers={"Accept": "application/json"},
            method="GET",
        )
        try:
            with urlopen(request, timeout=self.config.timeout) as response:
                body = response.read()
        except (URLError, TimeoutError, socket.timeout, OSError) as error:
            reason = getattr(error, "reason", error)
            raise ProviderUnavailableError(
                self.name, f"cannot reach {endpoint}: {reason}"
            ) from error

        try:
            return json.loads(body)
        except (JSONDecodeError, UnicodeDecodeError) as error:
            raise ProviderFailureError(
                self.name, Operation.LIST.value, "response is not valid JSON"
            ) from error

    def _parse_api_records(
        self, payload: object, operation: Operation
    ) -> list[ModelRecord]:
        if not isinstance(payload, dict) or "data" not in payload:
            self._malformed(operation, "expected an object containing 'data'")
        models = payload["data"]
        if not isinstance(models, list):
            self._malformed(operation, "'data' must be an array")

        records: list[ModelRecord] = []
        for index, model in enumerate(models):
            if not isinstance(model, dict):
                self._malformed(operation, f"data[{index}] must be an object")
            model_id = model.get("id")
            if not isinstance(model_id, str) or not model_id:
                self._malformed(
                    operation, f"data[{index}].id must be a non-empty string"
                )

            attributes = {"source": "api"}
            for key in ("object", "owned_by"):
                value = model.get(key)
                if value is not None:
                    if not isinstance(value, str):
                        self._malformed(
                            operation, f"data[{index}].{key} must be a string"
                        )
                    attributes[f"api.{key}"] = value
            created = model.get("created")
            if created is not None:
                if (
                    not isinstance(created, int)
                    or isinstance(created, bool)
                    or created < 0
                ):
                    self._malformed(
                        operation,
                        f"data[{index}].created must be a non-negative integer",
                    )
                attributes["api.created"] = str(created)

            records.append(
                ModelRecord(
                    provider=self.name,
                    model_id=model_id,
                    attributes=attributes,
                )
            )
        return records

    def _discover_files(self) -> tuple[list[ModelRecord], list[str]]:
        records: list[ModelRecord] = []
        errors: list[str] = []
        for root in self.config.model_roots:
            try:
                if not root.exists():
                    raise FileNotFoundError("root does not exist")
                if not root.is_dir():
                    raise NotADirectoryError("root is not a directory")
            except OSError as error:
                errors.append(f"{root}: {error}")
                continue

            walk_errors: list[OSError] = []
            for directory, directory_names, file_names in os.walk(
                root, onerror=walk_errors.append
            ):
                directory_names.sort()
                for file_name in sorted(file_names):
                    path = Path(directory, file_name)
                    if path.suffix.lower() not in MODEL_FILE_SUFFIXES:
                        continue
                    try:
                        if not path.is_file():
                            continue
                        size = path.stat().st_size
                    except OSError as error:
                        errors.append(f"{path}: {error}")
                        continue
                    relative_path = path.relative_to(root)
                    model_id = relative_path.with_suffix("").as_posix()
                    records.append(
                        ModelRecord(
                            provider=self.name,
                            model_id=model_id,
                            size_bytes=size,
                            location=str(path),
                            attributes={
                                "filesystem.extension": path.suffix.lower(),
                                "filesystem.relative_path": relative_path.as_posix(),
                                "filesystem.root": str(root),
                                "source": "filesystem",
                            },
                        )
                    )
            errors.extend(
                f"{Path(error.filename) if error.filename else root}: {error}"
                for error in walk_errors
            )
        return records, errors

    def _deduplicate(
        self,
        api_records: list[ModelRecord],
        file_records: list[ModelRecord],
    ) -> list[ModelRecord]:
        api_by_id: dict[str, list[ModelRecord]] = defaultdict(list)
        for record in api_records:
            api_by_id[record.model_id].append(record)

        merged_api = {
            model_id: self._merge_api_records(records)
            for model_id, records in api_by_id.items()
        }
        matched_ids: set[str] = set()
        output: list[ModelRecord] = []
        seen_files: set[tuple[str, str | None]] = set()
        for record in sorted(
            file_records, key=lambda item: (item.model_id, item.location or "")
        ):
            file_key = (record.model_id, record.location)
            if file_key in seen_files:
                continue
            seen_files.add(file_key)
            api_record = merged_api.get(record.model_id)
            if api_record is None:
                output.append(record)
                continue
            matched_ids.add(record.model_id)
            attributes = dict(api_record.attributes)
            attributes.update(record.attributes)
            attributes["source"] = "api,filesystem"
            output.append(
                ModelRecord(
                    provider=self.name,
                    model_id=record.model_id,
                    size_bytes=record.size_bytes,
                    location=record.location,
                    attributes=attributes,
                )
            )

        output.extend(
            record
            for model_id, record in sorted(merged_api.items())
            if model_id not in matched_ids
        )
        return output

    def _merge_api_records(self, records: list[ModelRecord]) -> ModelRecord:
        model_id = records[0].model_id
        values: dict[str, set[str]] = defaultdict(set)
        for record in records:
            for key, value in record.attributes.items():
                values[key].add(value)
        attributes = {
            key: (
                next(iter(items))
                if len(items) == 1
                else json.dumps(sorted(items), separators=(",", ":"))
            )
            for key, items in values.items()
        }
        return ModelRecord(
            provider=self.name,
            model_id=model_id,
            attributes=attributes,
        )

    def _malformed(self, operation: Operation, reason: str) -> NoReturn:
        raise ProviderFailureError(
            self.name, operation.value, f"malformed response: {reason}"
        )

import unittest

from model_storage_checker.errors import UnsupportedProviderError
from model_storage_checker.models import Operation, ProviderResult
from model_storage_checker.providers import ProviderRegistry


class StubProvider:
    name = "stub"

    def run(self, operation: Operation) -> ProviderResult:
        return ProviderResult.success(self.name, operation)


class ProviderRegistryTests(unittest.TestCase):
    def test_names_are_sorted(self) -> None:
        registry = ProviderRegistry(
            (StubProvider(),), unsupported_names=("z-provider", "a-provider")
        )

        self.assertEqual(registry.names, ("a-provider", "stub", "z-provider"))

    def test_registered_provider_runs(self) -> None:
        registry = ProviderRegistry((StubProvider(),))

        result = registry.run("stub", Operation.LIST)

        self.assertEqual(result, ProviderResult.success("stub", Operation.LIST))

    def test_unknown_or_declared_unsupported_provider_is_explicit(self) -> None:
        registry = ProviderRegistry(unsupported_names=("planned",))

        for provider in ("planned", "unknown"):
            with self.subTest(provider=provider):
                with self.assertRaisesRegex(UnsupportedProviderError, provider):
                    registry.run(provider, Operation.LIST)

if __name__ == "__main__":
    unittest.main()
    unittest.main()

#!/bin/sh
set -eu

message_file=$1
session_id=${COPILOT_AGENT_SESSION_ID:?COPILOT_AGENT_SESSION_ID is required}

python3 - "$message_file" "$session_id" <<'PY'
from pathlib import Path
import sys

path = Path(sys.argv[1])
session_id = sys.argv[2]
